// ──────────────────────────────────────────────────────
// STEP: Extract & normalise the Razorpay payload
//
// Razorpay's payment.captured payload nests the data we care
// about inside payload.payment.entity. We also check for the
// custom metadata (called 'notes' in Razorpay) that the checkout
// page attached at the time the Razorpay order was created.
// ──────────────────────────────────────────────────────

const body = $input.item.json.body;
const payment = body.payload?.payment?.entity || {};
const notes = payment.notes || {}; // Custom metadata from checkout

// The checkout UI should pass these in Razorpay order notes:
// notes.supabase_order_id  — the UUID from our orders table
// notes.client_id           — the client's profile UUID
// notes.service_id          — which service was purchased
// notes.client_name         — display name for WhatsApp msg
// notes.client_phone        — WhatsApp number (+91...)
// notes.client_email        — for email confirmation
// notes.business_name       — for the notification message

if (!notes.supabase_order_id) {
  throw new Error('Missing supabase_order_id in payment notes. Check your checkout integration.');
}

return [{
  json: {
    // Razorpay identifiers
    razorpay_payment_id:  payment.id,
    razorpay_order_id:    payment.order_id,
    amount_paise:         payment.amount,          // Razorpay uses paise (₹ × 100)
    amount_inr:           payment.amount / 100,    // Convert to rupees
    payment_method:       payment.method,          // 'upi', 'card', 'netbanking'
    currency:             payment.currency,
    captured_at:          new Date(payment.created_at * 1000).toISOString(),

    // Our app identifiers (from checkout notes)
    supabase_order_id:    notes.supabase_order_id,
    client_id:            notes.client_id,
    service_id:           notes.service_id,
    client_name:          notes.client_name || 'Valued Client',
    client_phone:         notes.client_phone,
    client_email:         notes.client_email,
    business_name:        notes.business_name || notes.client_name,
  }
}];

// ──────────────────────────────────────────────────────
// STEP: Parse the AI assignment result
//
// ai_assign_order() returns a JSONB object with the routing
// decision: which pod was chosen, which intern was assigned,
// what the delivery date is, etc. We merge this with the
// payment data from earlier steps so the WhatsApp message
// has everything it needs.
// ──────────────────────────────────────────────────────

const assignResult = $input.item.json; // JSONB from Postgres function
const paymentData = $('🔍 Extract Payment Data').item.json;

// Build the delivery date string for human display
const deliveryDate = assignResult.delivery_due
  ? new Date(assignResult.delivery_due).toLocaleDateString('en-IN', {
      day: 'numeric', month: 'long', year: 'numeric'
    })
  : 'within the committed window';

// Format the amount nicely
const amountFormatted = '₹' + Number(paymentData.amount_inr).toLocaleString('en-IN');

return [{
  json: {
    ...paymentData,
    // From AI assignment result
    assigned_pod:     assignResult.matched_pod,
    assigned_intern:  assignResult.assigned_to,
    delivery_due:     assignResult.delivery_due,
    delivery_display: deliveryDate,
    amount_display:   amountFormatted,
    order_number:     assignResult.order_number || paymentData.supabase_order_id.slice(0,8).toUpperCase(),
    // Portal deep link
    portal_url:       `${process.env.APP_URL || 'https://watermelon.in'}/portal/orders/${paymentData.supabase_order_id}`,
  }
}];

