// ──────────────────────────────────────────────────────
// STEP: Build the at-risk client summary for the ops team
//
// Formats all at-risk clients into a single WhatsApp message.
// If there are no at-risk clients, we skip sending.
// ──────────────────────────────────────────────────────

const clients = $input.all().map(item => item.json);

if (clients.length === 0) {
  return [{ json: { skip: true, message: 'No at-risk clients this week. All green! 🟢' } }];
}

const lines = clients.map((c, i) =>
  `${i + 1}. *${c.profiles.business_name}* — Score: ${c.score}%`
).join('\n');

const message = `🍉 *Watermelon Ops — Weekly At-Risk Report*

⚠️ ${clients.length} client${clients.length > 1 ? 's' : ''} need attention this week:\n\n${lines}\n\nPlease proactively reach out to these accounts before the week ends.\n\n📊 View all: ${process.env.APP_URL}/ops/clients`;

return [{ json: { skip: false, message, client_count: clients.length } }];
